def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def merge(name: str | None, status: str | None) -> None:
        if not name or not status:
            return
        order = {"pass": 0, "skip": 1, "fail": 2}
        previous = results.get(name)
        if previous is None or order[status] > order[previous]:
            results[name] = status

    def norm(outcome: str | None) -> str | None:
        if not outcome:
            return None
        o = outcome.strip().lower()
        if o in ("passed", "pass", "success", "succeeded", "ok"):
            return "pass"
        if o in ("skipped", "skip", "notexecuted", "ignored", "inconclusive", "not-run", "notrun"):
            return "skip"
        if o in ("failed", "fail", "error", "timeout", "aborted", "canceled", "cancelled", "crashed"):
            return "fail"
        return "fail"

    def strip_ns(tag: str) -> str:
        return tag.rsplit("}", 1)[-1]

    def parse_xml(text: str) -> None:
        try:
            root = ET.fromstring(text)
        except Exception:
            return
        for elem in root.iter():
            tag = strip_ns(elem.tag)
            if tag in ("UnitTestResult", "TestResult"):
                name = elem.attrib.get("testName") or elem.attrib.get("name")
                outcome = elem.attrib.get("outcome") or elem.attrib.get("result")
                merge(name, norm(outcome))
            elif tag == "testcase":
                name = elem.attrib.get("name")
                classname = elem.attrib.get("classname")
                full = f"{classname}.{name}" if classname else name
                status = "pass"
                for child in elem:
                    ctag = strip_ns(child.tag)
                    if ctag in ("failure", "error"):
                        status = "fail"
                        break
                    if ctag == "skipped":
                        status = "skip"
                merge(full, status)

    # Parse XML fragments for TRX/JUnit concatenated logs
    for match in re.finditer(r"(<TestRun\b[\s\S]*?</TestRun>)", log):
        parse_xml(match.group(1))
    for match in re.finditer(r"(<testsuites\b[\s\S]*?</testsuites>)", log, re.IGNORECASE):
        parse_xml(match.group(1))
    for match in re.finditer(r"(<testsuite\b[\s\S]*?</testsuite>)", log, re.IGNORECASE):
        parse_xml(match.group(1))

    if not results:
        parse_xml(log.strip())

    # Regex fallback for TRX UnitTestResult/TestResult tags
    for match in re.finditer(r"<(UnitTestResult|TestResult)\b[^>]*>", log, re.IGNORECASE):
        tag = match.group(0)
        name_match = re.search(r'\btestName="([^"]+)"', tag) or re.search(r'\bname="([^"]+)"', tag)
        outcome_match = re.search(r'\boutcome="([^"]+)"', tag) or re.search(r'\bresult="([^"]+)"', tag)
        if name_match and outcome_match:
            merge(name_match.group(1), norm(outcome_match.group(1)))

    # Text-based test outputs
    for line in log.splitlines():
        text = line.strip()
        m = re.search(r"(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)", text)
        if m:
            merge(m.group(1), norm(m.group(2)))
            continue
        m = re.search(r"^(\S+)\s+\.\.\.\s+(ok|OK|FAIL|FAILED|ERROR|SKIP|SKIPPED)", text)
        if m:
            merge(m.group(1), norm(m.group(2)))
            continue
        m = re.search(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", text)
        if m:
            merge(m.group(2), norm(m.group(1)))
            continue
        m = re.search(r"^[\s]*([✓✕○])\s+(.+)$", text)
        if m:
            symbol = m.group(1)
            name = m.group(2).strip()
            if symbol == "✓":
                status = "pass"
            elif symbol == "○":
                status = "skip"
            else:
                status = "fail"
            merge(name, status)
            continue

    return results
